class Solution:
    def maximizeWin(self, prizePositions: list[int], k: int) -> int:
        n = len(prizePositions)
        pre = [0] * (n + 1)
        l = 0
        ans = 0
        for r in range(n):
            while prizePositions[r] - prizePositions[l] > k:
                l += 1
            cnt = r - l + 1
            ans = max(ans, cnt + pre[l])
            pre[r + 1] = max(pre[r], cnt)
        return ans

class Solution {
public:
    int maximizeWin(std::vector<int>& prizePositions, int k) {
        int n = prizePositions.size();
        std::vector<int> pre(n + 1, 0);
        int l = 0, ans = 0;
        for (int r = 0; r < n; ++r) {
            while (prizePositions[r] - prizePositions[l] > k) l++;
            int cnt = r - l + 1;
            ans = std::max(ans, cnt + pre[l]);
            pre[r + 1] = std::max(pre[r], cnt);
        }
        return ans;
    }
};

class Solution {
    public int maximizeWin(int[] prizePositions, int k) {
        int n = prizePositions.length;
        int[] pre = new int[n + 1];
        int l = 0, ans = 0;
        for (int r = 0; r < n; r++) {
            while (prizePositions[r] - prizePositions[l] > k) l++;
            int cnt = r - l + 1;
            ans = Math.max(ans, cnt + pre[l]);
            pre[r + 1] = Math.max(pre[r], cnt);
        }
        return ans;
    }
}

var maximizeWin = function(prizePositions, k) {
    const n = prizePositions.length;
    const pre = new Int32Array(n + 1);
    let l = 0, ans = 0;
    for (let r = 0; r < n; r++) {
        while (prizePositions[r] - prizePositions[l] > k) l++;
        const cnt = r - l + 1;
        if (cnt + pre[l] > ans) ans = cnt + pre[l];
        pre[r + 1] = Math.max(pre[r], cnt);
    }
    return ans;
};
